const TABLE_CAT  = 'tefas_best_category_rates';
const TABLE_FUND = 'tefas_best_fund_rates';

const period = $('When Executed by Another Workflow').first().json.period;
const payload = items[0].json;

const results = [];

function esc(s) {
  if (s === undefined || s === null) return '';
  return String(s).replace(/'/g, "''");
}

function asArray(x) {
  if (x === undefined || x === null) return [];
  if (typeof x === 'string') {
    try { x = JSON.parse(x); } catch { return []; }
  }
  return Array.isArray(x) ? x : [];
}

function numOrNull(x) {
  if (x === undefined || x === null) return 'NULL';
  const n = Number(x);
  return Number.isFinite(n) ? n : 'NULL';
}

if (period === undefined || period === null) {
  return [{ json: { error: 'period yok' } }];
}

const resultList = asArray(payload.resultList);

for (const cat of resultList) {
  // KATEGORİ ADI 
  const categoryName = cat?.fonTurAciklama ? String(cat.fonTurAciklama).trim() : null;
  if (!categoryName) continue;

  const getiri = numOrNull(cat?.fonDonemGetiri);
  const pazar  = numOrNull(cat?.pazarBuyukluk);

  // 1) Kategori yoksa ekle 
  const sqlEnsureCat = `
    INSERT INTO tefas_category (name)
    SELECT '${esc(categoryName)}'
    WHERE NOT EXISTS (
      SELECT 1 FROM tefas_category WHERE name = '${esc(categoryName)}'
    );
  `.trim();
  results.push({ json: { query: sqlEnsureCat } });

  const sqlCat = `
    INSERT INTO ${TABLE_CAT} (period_id, category_id, getiri, pazarbuyukluk, fetched_at)
    VALUES (
      ${period}, 
      (SELECT id FROM tefas_category WHERE name = '${esc(categoryName)}' LIMIT 1), 
      ${getiri}, 
      ${pazar}, 
      CURDATE()
    )
    ON DUPLICATE KEY UPDATE
      getiri = VALUES(getiri),
      pazarbuyukluk = VALUES(pazarbuyukluk);
  `.trim();

  results.push({ json: { query: sqlCat } });

  // ALT FONLAR: resultList[].obje1List[].data[]
  const groups = asArray(cat?.obje1List);

  for (const g of groups) {
    const funds = asArray(g?.data);

    for (const f of funds) {
      const fundCode = f?.name ? String(f.name).trim() : null; // örn: GJD
      if (!fundCode) continue;

      const rate = numOrNull(f?.y);

      const sqlFund = `
        INSERT INTO ${TABLE_FUND} (period_id, fund_id, category_id, rate, fetched_at)
        SELECT
          ${period},
          tf.id,
          (SELECT id FROM tefas_category WHERE name = '${esc(categoryName)}' LIMIT 1),
          ${rate},
          CURDATE()
        FROM tefas_funds tf
        WHERE tf.code = '${esc(fundCode)}'
        LIMIT 1
        ON DUPLICATE KEY UPDATE
          rate = VALUES(rate);
      `.trim();

      results.push({ json: { query: sqlFund } });
    }
  }
}

return results;
